sys_script_include.script:
var JAKScriptInclude_Utils = Class.create();
JAKScriptInclude_Utils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getUserName: function() {
        var userSysId = this.getParameter('sysparm_userSysId');
        var grUser = new GlideRecord('sys_user');
        if (grUser.get(userSysId)) {
            var result = {
                first_name: grUser.getValue('first_name'),
                last_name: grUser.getValue('last_name'),
                email: grUser.getValue('email'),
                department: grUser.department.getDisplayValue()
            };
            return JSON.stringify(result);
        }
        return '';
    },
	getCISupportGroup: function(){
		var ciSysId = this.getParameter('sysparm_ciSysId');
		gs.info('CI Sys ID = ' + ciSysId);
		var grCI = new GlideRecord('cmdb_ci_computer');

		if(grCI.get(ciSysId)){
			gs.info('Support Group = ' + grCI.getValue('support_group'));
			return grCI.getValue('support_group');
		}
		return '';
	},
	getCICount: function(){
		var CntCiSysId = this.getParameter('sysparm_CICountSysId');
		var grIncident = new GlideAggregate('incident');
		grIncident.addQuery('cmdb_ci',CntCiSysId);
		grIncident.addAggregate('COUNT');
		grIncident.query();
		if (grIncident.next()) {
			return grIncident.getAggregate('COUNT');
		}
		return '0';
	},
    type: 'JAKScriptInclude_Utils'
});
